CREATE TABLE Users(id varchar(36) NOT NULL PRIMARY KEY, username nvarchar(80) NOT NULL UNIQUE, name nvarchar(120) NOT NULL, passwordHash varchar(100) NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('Admin','Receptionist','Cleaner')), enabled bit NOT NULL DEFAULT 1, authVersion int NOT NULL DEFAULT 1);
CREATE TABLE RefreshSessions(id varchar(36) PRIMARY KEY,userId varchar(36) NOT NULL REFERENCES Users(id),tokenHash varchar(64) NOT NULL UNIQUE,expiresAt datetime2 NOT NULL,revoked bit NOT NULL DEFAULT 0);
CREATE TABLE RoomTypes(id varchar(36) PRIMARY KEY,name nvarchar(100) NOT NULL,capacity int NOT NULL CHECK(capacity>0),rateJson nvarchar(max) NOT NULL CHECK(ISJSON(rateJson)=1));
CREATE TABLE Rooms(id varchar(36) PRIMARY KEY,number nvarchar(20) NOT NULL UNIQUE,typeId varchar(36) NOT NULL REFERENCES RoomTypes(id),zone nvarchar(40) NOT NULL,enabled bit NOT NULL DEFAULT 1,cleanState varchar(10) NOT NULL DEFAULT 'CLEAN' CHECK(cleanState IN ('CLEAN','DIRTY')),cycle int NOT NULL DEFAULT 0,photoUrl nvarchar(500) NULL);
CREATE TABLE Customers(id varchar(36) PRIMARY KEY,name nvarchar(120) NOT NULL,phone varchar(30) NOT NULL,notes nvarchar(500) NOT NULL DEFAULT '');
CREATE INDEX IX_Customers_phone ON Customers(phone);
CREATE TABLE Bookings(id varchar(36) PRIMARY KEY,roomId varchar(36) NOT NULL REFERENCES Rooms(id),customerId varchar(36) NOT NULL REFERENCES Customers(id),startsAt datetime2 NOT NULL,endsAt datetime2 NOT NULL,status varchar(20) NOT NULL CHECK(status IN ('CONFIRMED','CANCELLED','CHECKED_IN')),guests int NOT NULL CHECK(guests>0),mode varchar(10) NOT NULL CHECK(mode IN ('HOUR','NIGHT','DAY')),createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CHECK(endsAt>startsAt));
CREATE INDEX IX_Bookings_availability ON Bookings(roomId,status,startsAt,endsAt);
CREATE TABLE Stays(id varchar(36) PRIMARY KEY,roomId varchar(36) NOT NULL REFERENCES Rooms(id),customerId varchar(36) NOT NULL REFERENCES Customers(id),bookingId varchar(36) NULL UNIQUE REFERENCES Bookings(id),startedAt datetime2 NOT NULL,expectedEnd datetime2 NOT NULL,endedAt datetime2 NULL,status varchar(10) NOT NULL CHECK(status IN ('OPEN','CLOSED')),guests int NOT NULL CHECK(guests>0),mode varchar(10) NOT NULL CHECK(mode IN ('HOUR','NIGHT','DAY')),rateJson nvarchar(max) NOT NULL CHECK(ISJSON(rateJson)=1),cycle int NOT NULL,dnd bit NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX UX_Stays_open ON Stays(roomId) WHERE status='OPEN';
CREATE TABLE Services(id varchar(36) PRIMARY KEY,code varchar(30) NOT NULL UNIQUE,name nvarchar(120) NOT NULL,unit nvarchar(30) NOT NULL,price int NOT NULL CHECK(price>=0),cleaning bit NOT NULL DEFAULT 0,fullClean bit NOT NULL DEFAULT 0,enabled bit NOT NULL DEFAULT 1);
CREATE TABLE StayServiceItems(id varchar(36) PRIMARY KEY,stayId varchar(36) NOT NULL REFERENCES Stays(id),serviceId varchar(36) NOT NULL REFERENCES Services(id),name nvarchar(120) NOT NULL,unitPrice int NOT NULL CHECK(unitPrice>=0),quantity int NOT NULL CHECK(quantity>0),taskId varchar(36) NULL UNIQUE);
CREATE TABLE Invoices(id varchar(36) PRIMARY KEY,stayId varchar(36) NOT NULL UNIQUE REFERENCES Stays(id),total int NOT NULL CHECK(total>=0),roomJson nvarchar(max) NOT NULL,discount int NOT NULL DEFAULT 0,surcharge int NOT NULL DEFAULT 0,debtReason nvarchar(500) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE InvoiceLines(id varchar(36) PRIMARY KEY,invoiceId varchar(36) NOT NULL REFERENCES Invoices(id),name nvarchar(120) NOT NULL,quantity int NOT NULL,unitPrice int NOT NULL,total int NOT NULL);
CREATE TABLE Receipts(id varchar(36) PRIMARY KEY,bookingId varchar(36) NULL REFERENCES Bookings(id),stayId varchar(36) NULL REFERENCES Stays(id),amount int NOT NULL CHECK(amount>0),method varchar(10) NOT NULL CHECK(method IN ('CASH','TRANSFER')),createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),actorId varchar(36) NOT NULL REFERENCES Users(id),CHECK(bookingId IS NOT NULL OR stayId IS NOT NULL));
CREATE TABLE PaymentAllocations(receiptId varchar(36) NOT NULL REFERENCES Receipts(id),invoiceId varchar(36) NOT NULL REFERENCES Invoices(id),amount int NOT NULL CHECK(amount>0),PRIMARY KEY(receiptId,invoiceId));
CREATE TABLE Adjustments(id varchar(36) PRIMARY KEY,invoiceId varchar(36) NOT NULL REFERENCES Invoices(id),amount int NOT NULL CHECK(amount>0),reason nvarchar(500) NOT NULL,actorId varchar(36) NOT NULL REFERENCES Users(id),createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Refunds(id varchar(36) PRIMARY KEY,invoiceId varchar(36) NOT NULL REFERENCES Invoices(id),amount int NOT NULL CHECK(amount>0),reason nvarchar(500) NOT NULL,actorId varchar(36) NOT NULL REFERENCES Users(id),createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE CleanerProfiles(userId varchar(36) PRIMARY KEY REFERENCES Users(id),zone nvarchar(40) NOT NULL,skills nvarchar(300) NOT NULL,accepting bit NOT NULL DEFAULT 0,ratingSum int NOT NULL DEFAULT 0,ratingCount int NOT NULL DEFAULT 0,lastClosedAt datetime2 NULL);
CREATE TABLE CleanerShifts(id varchar(36) PRIMARY KEY,userId varchar(36) NOT NULL REFERENCES Users(id),startsAt datetime2 NOT NULL,endsAt datetime2 NOT NULL,CHECK(endsAt>startsAt));
CREATE TABLE HousekeepingTasks(id varchar(36) PRIMARY KEY,roomId varchar(36) NOT NULL REFERENCES Rooms(id),stayId varchar(36) NOT NULL REFERENCES Stays(id),serviceId varchar(36) NOT NULL REFERENCES Services(id),source varchar(20) NOT NULL,windowStart datetime2 NOT NULL,windowEnd datetime2 NOT NULL,status varchar(30) NOT NULL CHECK(status IN ('PENDING','ASSIGNED','IN_PROGRESS','AWAITING_VERIFICATION','COMPLETED','CANCELLED')),checklistJson nvarchar(max) NOT NULL,priceSnapshot int NOT NULL CHECK(priceSnapshot>=0),entryConsent bit NOT NULL,notes nvarchar(1000) NOT NULL DEFAULT '',cycle int NOT NULL,dedupeKey varchar(180) NOT NULL UNIQUE,version int NOT NULL DEFAULT 1,offerRound int NOT NULL DEFAULT 0,escalated bit NOT NULL DEFAULT 0,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CHECK(windowEnd>windowStart));
CREATE INDEX IX_Tasks_dispatch ON HousekeepingTasks(status,windowStart);
CREATE TABLE CleaningOffers(id varchar(36) PRIMARY KEY,taskId varchar(36) NOT NULL REFERENCES HousekeepingTasks(id),cleanerId varchar(36) NOT NULL REFERENCES Users(id),round int NOT NULL,taskVersion int NOT NULL,expiresAt datetime2 NOT NULL,status varchar(12) NOT NULL CHECK(status IN ('PENDING','ACCEPTED','REJECTED','EXPIRED','REVOKED')),scoreBreakdown nvarchar(max) NOT NULL,UNIQUE(taskId,cleanerId,round));
CREATE TABLE CleaningAssignments(id varchar(36) PRIMARY KEY,taskId varchar(36) NOT NULL REFERENCES HousekeepingTasks(id),cleanerId varchar(36) NOT NULL REFERENCES Users(id),offerId varchar(36) NULL UNIQUE REFERENCES CleaningOffers(id),assignedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),startedAt datetime2 NULL,submittedAt datetime2 NULL,closedAt datetime2 NULL,status varchar(20) NOT NULL,isActive bit NOT NULL DEFAULT 1,checklistJson nvarchar(max) NULL);
CREATE UNIQUE INDEX UX_Assignment_active_task ON CleaningAssignments(taskId) WHERE isActive=1;
CREATE UNIQUE INDEX UX_Assignment_active_cleaner ON CleaningAssignments(cleanerId) WHERE isActive=1;
CREATE TABLE CleaningReviews(taskId varchar(36) PRIMARY KEY REFERENCES HousekeepingTasks(id),cleanerId varchar(36) NOT NULL REFERENCES Users(id),rating int NOT NULL CHECK(rating BETWEEN 1 AND 5),comment nvarchar(500) NOT NULL DEFAULT '');
CREATE TABLE GuestAccessTokens(id varchar(36) PRIMARY KEY,stayId varchar(36) NOT NULL REFERENCES Stays(id),tokenHash varchar(64) NOT NULL UNIQUE,expiresAt datetime2 NOT NULL,revoked bit NOT NULL DEFAULT 0);
CREATE TABLE Notifications(id varchar(36) PRIMARY KEY,userId varchar(36) NOT NULL REFERENCES Users(id),title nvarchar(150) NOT NULL,body nvarchar(500) NOT NULL,taskId varchar(36) NULL REFERENCES HousekeepingTasks(id),isRead bit NOT NULL DEFAULT 0,eventKey varchar(200) NOT NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UNIQUE(userId,eventKey));
CREATE TABLE DeviceTokens(token varchar(200) PRIMARY KEY,userId varchar(36) NOT NULL REFERENCES Users(id));
CREATE TABLE OutboxEvents(id varchar(36) PRIMARY KEY,eventKey varchar(200) NOT NULL UNIQUE,userId varchar(36) NOT NULL REFERENCES Users(id),payloadJson nvarchar(max) NOT NULL,status varchar(12) NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,nextAttemptAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),lastError nvarchar(500) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_Outbox_delivery ON OutboxEvents(status,nextAttemptAt);
CREATE TABLE Maintenance(id varchar(36) PRIMARY KEY,roomId varchar(36) NOT NULL REFERENCES Rooms(id),startsAt datetime2 NOT NULL,endsAt datetime2 NOT NULL,reason nvarchar(500) NOT NULL,resolvedAt datetime2 NULL,CHECK(endsAt>startsAt));
CREATE TABLE AuditLogs(id varchar(36) PRIMARY KEY,actorId varchar(36) NULL REFERENCES Users(id),action varchar(80) NOT NULL,entityId varchar(36) NOT NULL,details nvarchar(max) NOT NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE IdempotencyRecords(actorKey varchar(80) NOT NULL,requestKey varchar(100) NOT NULL,requestHash varchar(64) NOT NULL,resultJson nvarchar(max) NOT NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),PRIMARY KEY(actorKey,requestKey));
